      { t: 'mc', q: { q: 'Which word has the CVC pattern for a short vowel?', c: ['cape', 'hop', 'rain'], a: 1, say: true, h: 'Find one vowel between two consonants.', ex: 'Hop is h-o-p: one vowel between two consonants.' } }
